"use strict"; // Enable strict mode for the whole script

try {
  // In sloppy mode, this silently creates a global window.myVar
  // In strict mode, it throws a ReferenceError
  myVar = "Hello World!"; 
} catch (e) {
  console.log("Error caught:", e.message);
}

function sloppyFunction() {
  // If we didn't have "use strict" at the top, we could do:
  // "use strict"; just for this function
}

function checkThis() {
  console.log(this);
}

checkThis(); // undefined in strict mode, but Window in sloppy mode
